import Foundation

// MR-1638. Foundation-only BY DESIGN, and in its own file for the same reason
// ConnectWire.swift is: the heartbeat reply is part of the wire contract
// (`$defs.HeartbeatResponse` in contract/vpn-protocol.schema.json), and the
// only way to check the REAL model against it is to compile it into the test
// bundle, which cannot host APIClient.swift. See ConnectContractTests.

/// `HeartbeatResult.reason`: why the key is in the state the reply reports.
///
/// Mirrors `$defs.HeartbeatReason` in the vendored contract (generated by
/// birdo-web from `HEARTBEAT_REASONS` in backend/src/vpn/vpn.service.ts, #599),
/// which is where each meaning below comes from. `ConnectContractTests` fails
/// if the two lists drift, so a reason added by a re-vendor has to be added
/// here on purpose. Android twin: `HeartbeatResponse.reason`, read by
/// `HeartbeatPolicy`.
enum HeartbeatReason: String, CaseIterable, Sendable {
    /// The key is live and its server is ONLINE.
    case ok
    /// Connect to a different server. With `valid: true` the key is live but
    /// its server is not ONLINE; with `valid: false` the key was removed
    /// because its server was drained or deleted.
    case serverOffline = "server_offline"
    /// Ended on purpose: by the user, the account or a plan change. Stop, no
    /// automatic reconnect.
    case revoked
    /// A newer connection on the account took the slot. Stop, and NEVER
    /// reconnect automatically.
    case evicted
    /// Released by server housekeeping. One quiet rebuild is safe.
    case reaped
    /// The free data allowance is used up and the server ended the session
    /// (always with `quotaExceeded: true`). Stop, no automatic reconnect.
    case quotaExceeded = "quota_exceeded"
    /// No record of why: handle it as a reply without a reason.
    case notFound = "not_found"
}

/// Response of `POST /vpn/heartbeat/{keyId}`. `valid: false` means the
/// connection was revoked server-side (silent free-tier eviction) — the
/// client must disconnect and surface `message`. Fail-open on decode
/// surprises: an absent `valid` must never kill a live tunnel.
///
/// The host acts on `valid`, `serverOnline` and `message` (VpnViewModel's
/// heartbeat); `reason` and the quota fields are decoded so the model holds
/// the whole contract, and nothing reads them yet.
struct HeartbeatResult: Sendable {
    let valid: Bool
    let serverOnline: Bool?
    let message: String?
    /// nil when the reply has none (a backend before birdo-web #599) or one
    /// this build does not know; the contract says to treat both alike.
    let reason: HeartbeatReason?
    /// FREE-TIER CAP: true while the account is over its data allowance, and
    /// with every `quota_exceeded` reason. Absent means false.
    let quotaExceeded: Bool
    /// ISO-8601 instant the server ends a free session in its grace window.
    let quotaGraceEndsAt: String?
    /// Seconds until `quotaGraceEndsAt`, from the server's clock.
    let quotaGraceSecondsRemaining: TimeInterval?
}

extension HeartbeatResult: Decodable {
    private enum CodingKeys: String, CodingKey {
        case valid, serverOnline, message
        case reason, quotaExceeded, quotaGraceEndsAt, quotaGraceSecondsRemaining
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        valid = try c.decodeIfPresent(Bool.self, forKey: .valid) ?? true
        serverOnline = try c.decodeIfPresent(Bool.self, forKey: .serverOnline)
        message = try c.decodeIfPresent(String.self, forKey: .message)
        // `try?` from here on: these fields are additive, and a surprise in
        // one of them must never fail the reply whose `valid` ends a session.
        // A plain String first, so an unknown reason is nil rather than an
        // error.
        reason = (try? c.decodeIfPresent(String.self, forKey: .reason)).flatMap(HeartbeatReason.init(rawValue:))
        quotaExceeded = (try? c.decodeIfPresent(Bool.self, forKey: .quotaExceeded)) ?? false
        quotaGraceEndsAt = try? c.decodeIfPresent(String.self, forKey: .quotaGraceEndsAt)
        quotaGraceSecondsRemaining = try? c.decodeIfPresent(TimeInterval.self, forKey: .quotaGraceSecondsRemaining)
    }
}
